function silenceVideo(video){
 const enforceSilence=()=>{
  video.defaultMuted=true;
  if(!video.muted)video.muted=true;
  if(video.volume!==0)video.volume=0;
 };
 enforceSilence();
 video.addEventListener('volumechange',enforceSilence);
 video.addEventListener('play',enforceSilence);
}
document.querySelectorAll('video').forEach(silenceVideo);

function setupGifPairs(container){
 container.querySelectorAll('[data-gif-pair]').forEach(pair=>{
  let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const toggle=pair.querySelector('[data-gif-toggle]');
  const update=()=>{
   pair.querySelectorAll('[data-gif-src]').forEach(img=>{img.src=paused?img.dataset.stillSrc:img.dataset.gifSrc;});
   toggle.textContent=paused?'Play animations':'Pause animations';
   toggle.setAttribute('aria-pressed',String(paused));
  };
  toggle.addEventListener('click',()=>{paused=!paused;update();});
  update();
 });
}

// Portrait assets reviewed against their displayed orientation and existing crops.
const portraitFigureAssets=new Set([
 'radar-integrated.jpg','tower.webp','field.webp','outdoor-testing.jpg',
 'inverter-four-cap.jpg','inverter-two-cap.jpg','inverter-failure.jpg',
 'bytes-networking.jpg','relay-demo-poster.jpg','bytes-video.jpg'
]);
function compactFigureDescriptions(container){
 container.querySelectorAll('figure.detail-figure').forEach(figure=>{
  if(figure.closest('.portrait-description-row'))return;
  const media=figure.querySelector('img,video');
  if(!media)return;
  const source=media.tagName==='VIDEO'?media.getAttribute('poster'):media.getAttribute('src');
  const asset=(source||'').split('?')[0].split('/').pop();
  if(!portraitFigureAssets.has(asset))return;
  // Existing galleries retain their own media and caption grouping.
  if(figure.closest('.code-evidence-grid,.radar-integration-pair,.radar-power-media,.reflector-animations,.detail-photo-pair,.inverter-hero-grid'))return;
  if(!figure.querySelector('figcaption'))return;
  const paragraphs=[];
  let previous=figure.previousElementSibling;
  while(previous&&previous.matches('p:not(.eyebrow):not(.chapter-number):not(.fine):not(.reference-line):not(.engineering-note)')){
   paragraphs.unshift(previous);
   previous=previous.previousElementSibling;
  }
  if(!paragraphs.length)return;
  const row=document.createElement('div');
  row.className='portrait-description-row';
  const description=document.createElement('div');
  description.className='figure-description-copy';
  paragraphs[0].before(row);
  paragraphs.forEach(paragraph=>description.appendChild(paragraph));
  row.append(description,figure);
  // The original figcaption stays beneath the media inside its figure.
 });
}

function layoutSchematicDescriptions(container){
 container.querySelectorAll('figure.detail-figure').forEach((figure,index)=>{
  const image=figure.querySelector('img');
  if(!image||!image.getAttribute('src').startsWith('assets/cpu-')||figure.closest('.scope-schematic'))return;
  const blocks=[];
  let previous=figure.previousElementSibling;
  while(previous&&previous.matches('p')){blocks.unshift(previous);previous=previous.previousElementSibling;}
  if(!previous||!previous.matches('h3'))return;
  blocks.unshift(previous);
  const section=document.createElement('section');
  section.className='scope-schematic cpu-schematic';
  if(!previous.id)previous.id='cpu-schematic-'+index;
  section.setAttribute('aria-labelledby',previous.id);
  previous.before(section);
  blocks.forEach(block=>section.appendChild(block));
  figure.classList.add('schematic-sheet');
  section.appendChild(figure);
 });
 container.querySelectorAll('.scope-schematic').forEach(section=>{
  if(section.classList.contains('schematic-description-row'))return;
  const figure=section.querySelector('.schematic-sheet');
  if(!figure)return;
  const description=document.createElement('div');
  description.className='schematic-description';
  Array.from(section.children).filter(child=>child!==figure).forEach(child=>description.appendChild(child));
  section.prepend(description);
  section.classList.add('schematic-description-row');
 });
}

const dialog=document.querySelector('dialog'),content=document.querySelector('#dialog-content');
dialog.setAttribute('aria-labelledby','detail-title');
function openProject(key){const p=projects[key];content.innerHTML=`<header class="detail-header"><p class="eyebrow">${p.label}</p><h2 id="detail-title">${p.title}</h2></header><nav class="detail-nav" aria-label="Project sections"><button type="button" data-jump="technical">01 / Project details</button><button type="button" data-jump="experience">02 / My experience</button><button type="button" data-dismiss>Close ×</button></nav><section class="detail-section" id="detail-technical" aria-labelledby="technical-title"><p class="eyebrow">01 / PROJECT DETAILS</p><h2 id="technical-title">Project details</h2>${p.technical}</section><section class="detail-section detail-experience" id="detail-experience" aria-labelledby="experience-title"><p class="eyebrow">02 / MY EXPERIENCE</p><h2 id="experience-title">${p.storyTitle}</h2>${p.story}</section>`;content.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>document.getElementById('detail-'+b.dataset.jump).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})));content.querySelector('[data-dismiss]').addEventListener('click',()=>dialog.close());dialog.showModal();if(signalCursor)dialog.appendChild(signalCursor);dialog.scrollTop=0;compactFigureDescriptions(content);layoutSchematicDescriptions(content);setupGifPairs(content);content.querySelectorAll('video').forEach(silenceVideo);content.querySelectorAll('video').forEach(video=>{
 const toggle=video.closest('figure').querySelector('[data-video-toggle]');
 const updateToggle=()=>{if(toggle)toggle.textContent=video.paused?'Play video':'Pause video';};
 if(toggle)toggle.addEventListener('click',()=>{if(video.paused){video.play().catch(updateToggle);}else{video.pause();}});
 video.addEventListener('play',updateToggle);
 video.addEventListener('pause',updateToggle);
 video.play().catch(updateToggle);
 updateToggle();
});}
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>openProject(b.dataset.project)));
document.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});

dialog.addEventListener('close',()=>{content.querySelectorAll('video').forEach(video=>video.pause());content.querySelectorAll('[data-gif-src]').forEach(img=>{img.src=img.dataset.stillSrc;});if(signalCursor)document.body.appendChild(signalCursor);});

if ('IntersectionObserver' in window && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
 const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal');observer.unobserve(entry.target)}}),{threshold:.08});
 document.querySelectorAll('.section-head,.photo-grid,.project-grid').forEach(el=>observer.observe(el));
}

const bytesEventVideo=document.querySelector('.bytes-event video');
if(bytesEventVideo){
 bytesEventVideo.muted=true;
 const startBytesVideo=()=>bytesEventVideo.play().catch(()=>{});
 startBytesVideo();
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)startBytesVideo()});
 if('IntersectionObserver' in window){
  new IntersectionObserver(entries=>entries.forEach(entry=>{
   if(entry.isIntersecting)startBytesVideo();
  }),{threshold:.12}).observe(bytesEventVideo);
 }
}

const signalCursor=document.querySelector('.signal-cursor');
if(signalCursor&&matchMedia('(hover:hover) and (pointer:fine) and (prefers-reduced-motion:no-preference)').matches){
 const interactive='a,button,[data-project],summary,input,textarea,select,video';
 let cursorX=-60,cursorY=-60,frame;
 const setCursorState=target=>signalCursor.classList.toggle('is-active',Boolean(target&&target.closest(interactive)));
 const drawCursor=()=>{signalCursor.style.transform=`translate3d(${cursorX-13}px,${cursorY}px,0)`;frame=null};
 document.addEventListener('pointermove',event=>{cursorX=event.clientX;cursorY=event.clientY;signalCursor.classList.remove('is-hidden');setCursorState(document.elementFromPoint(cursorX,cursorY));if(!frame)frame=requestAnimationFrame(drawCursor)});
 document.addEventListener('pointerover',event=>setCursorState(event.target));
 document.addEventListener('pointerdown',()=>signalCursor.classList.add('is-down'));
 document.addEventListener('pointerup',()=>signalCursor.classList.remove('is-down'));
 document.addEventListener('pointerleave',()=>signalCursor.classList.add('is-hidden'));
 window.addEventListener('blur',()=>signalCursor.classList.add('is-hidden'));
}
